void show_connections_window(HWND owner){if(connections_window&&IsWindow(connections_window)){ShowWindow(connections_window,SW_RESTORE);SetForegroundWindow(connections_window);return;}static bool registered{};auto instance=GetModuleHandleW(nullptr);if(!registered){WNDCLASSEXW wc{sizeof(wc)};wc.lpfnWndProc=proc;wc.hInstance=instance;wc.lpszClassName=L"KRMyceliaConnectionsWindow";wc.hCursor=LoadCursorW(nullptr,IDC_ARROW);wc.hbrBackground=(HBRUSH)(COLOR_WINDOW+1);registered=RegisterClassExW(&wc)!=0||GetLastError()==ERROR_CLASS_ALREADY_EXISTS;}auto hwnd=CreateWindowExW(0,L"KRMyceliaConnectionsWindow",L"KR Mycelia Memory – KI-Verbindungen",WS_OVERLAPPEDWINDOW,CW_USEDEFAULT,CW_USEDEFAULT,760,650,owner,nullptr,instance,nullptr);if(hwnd){ShowWindow(hwnd,SW_SHOW);UpdateWindow(hwnd);}}
